add_filter( 'woocommerce_email_styles', 'perfectpixel_email_custom_css', 20, 2 );

function perfectpixel_email_custom_css( $css, $email = null ) {
	$only = trim( '{{email_css_only_for}}' );
	if ( '' !== $only && ( ! $email || $email->id !== $only ) ) {
		return $css;
	}
	// Edit the rules below.
	$css .= '
		#template_container, #body_content_inner { font-family: Arial, Helvetica, sans-serif; }
		h1 { font-weight: 600; }
		h2, h3 { color: #2271b1; }
		.td { border-color: #e5e5e5 !important; }
		.order_item td { vertical-align: middle; }
	';
	return $css;
}
